--
-- Table structure for table `sys_message`
--

DROP TABLE IF EXISTS `sys_message`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `sys_message` (
  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息ID',
  `title` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '标题',
  `content` text COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '正文',
  `msg_type` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT 'send' COMMENT '消息类型：send/system',
  `sender_id` varchar(32) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '发送人用户ID',
  `tenant_id` int NOT NULL DEFAULT '1' COMMENT '租户ID(0=平台共享)',
  `receiver_count` int NOT NULL DEFAULT '0' COMMENT '接收人数',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  `updated_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6) COMMENT '更新时间',
  PRIMARY KEY (`id`),
  KEY `idx_message_tenant` (`tenant_id`,`created_at`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='站内信';
/*!40101 SET character_set_client = @saved_cs_client */;

