  `id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '主键',
  `message_id` char(36) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '消息ID',
  `user_id` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '接收人用户ID',
  `is_read` tinyint NOT NULL DEFAULT '0' COMMENT '0未读 1已读',
  `read_at` datetime(6) DEFAULT NULL COMMENT '阅读时间',
  `created_at` datetime(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) COMMENT '创建时间',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_message_user` (`message_id`,`user_id`),
  KEY `idx_message_user_user` (`user_id`,`is_read`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='站内信接收人';
